using System;
using System.Linq;
using System.Collections.Generic;
using System.Text.RegularExpressions;
namespace Lisichka {
 // A bounded conversation guide: choices and follow-up questions, never invented facts.
 public sealed class TopicConversation {
  sealed class Topic {
   public string Name,Pattern,Opening,Self;public string[] Questions;
   public Topic(string name,string pattern,string opening,string self,params string[] questions){Name=name;Pattern=pattern;Opening=opening;Self=self;Questions=questions;}
  }
  static readonly Topic[] topics={
   new Topic("Музыка",@"музык\w*|песн\w*|рок|джаз|поп|рэп","Какая музыка тебе сейчас близка — жанр, исполнитель или одна песня?","Для моего воображаемого лисьего вечера я бы выбрала мягкую мелодию с гитарой. А что выберешь ты?","Что в этой музыке цепляет тебя сильнее: слова, звучание или настроение?","Есть песня, которая особенно хорошо передаёт это ощущение?","С каким моментом твоей жизни она связана?","Какую музыку ты бы включил для идеального вечера?"),
   new Topic("Фильмы и сериалы",@"фильм\w*|кино|сериал\w*|аниме","Какой фильм или сериал запомнился тебе в последнее время? Можно начать с любимого жанра.","В лисьей истории я бы выбрала добрую сказку с уютным концом. Реальные фильмы я не смотрю, но могу обсудить твои впечатления.","Что запомнилось больше: герой, история или атмосфера?","Какой момент лучше всего это показывает?","Ты бы поступил так же, как герой, или иначе?","Какое послевкусие осталось после просмотра?"),
   new Topic("Игры",@"игр\w*|варкрафт|warcraft|майнкрафт|minecraft","Во что тебе нравится играть и что в этой игре привлекает?","Мне подошёл бы воображаемый лесной мир с исследованием и поиском ягод. А тебе ближе приключение, соревнование или строительство?","Тебе важнее исследование, победа или время с друзьями?","Вспомни один удачный или смешной игровой момент. Что произошло?","Что сделало этот момент особенным именно для тебя?","Что хочется попробовать в игре следующим?"),
   new Topic("Мечты и планы",@"мечт\w*|план\w*|будущ\w*","Есть что-то, что давно хочется попробовать — пусть даже совсем небольшое?","Если пофантазировать, я бы устроила маленькую библиотеку в лесном домике. А какой замысел согревает тебя?","Что в этой идее особенно привлекает?","Как мог бы выглядеть самый маленький первый шаг?","Что помогло бы сделать этот шаг легче?","Как ты поймёшь, что продвинулся, даже совсем немного?"),
   new Topic("Уют и отдых",@"уют\w*|отдых\w*|вечер","Как выглядит твой уютный вечер: тишина, прогулка, плед или что-то своё?","В нашем лисьем уголке это мягкий шарфик, тёплый свет и спокойный разговор. А какая деталь важнее тебе?","Что помогает тебе переключиться после долгого дня?","Что из этого можно устроить для себя уже сегодня?","Хочется провести такое время одному или с кем-то близким?","Какую маленькую деталь ты добавил бы для полного уюта?"),
   new Topic("Путешествия",@"путешеств\w*|поездк\w*|места|страны","Куда тебе хотелось бы отправиться — в знакомое любимое место или куда-то впервые?","В воображении я выбрала бы тихий лес с озером. Настоящих поездок у меня не было. А куда тянет тебя?","Что привлекает в этом месте: природа, люди, еда или ощущение новизны?","Как бы прошёл твой первый день там?","Что хотелось бы сохранить в памяти об этой поездке?","Есть похожее маленькое приключение, которое можно устроить поближе?"),
   new Topic("Воспоминания",@"воспомин\w*|детств\w*|ностальг\w*","Есть тёплое воспоминание, которым хочется поделиться? Можно выбрать совсем обычный день.","У меня нет настоящего детства, но в лисьей сказке был бы первый снег и огромный шарф. А какой момент вспоминается тебе?","Какая маленькая деталь той истории запомнилась особенно ярко?","Что ты чувствуешь, когда вспоминаешь этот момент?","Есть ли что-то из того уюта, что осталось в твоей жизни сейчас?","Хочется рассказать ещё один эпизод из этой истории?"),
   new Topic("Книги",@"книг\w*|чтени\w*|литератур\w*","Какую книгу ты читаешь или хотел бы обсудить? Можно назвать жанр.","Для воображаемой лисьей полки я бы выбрала сказки о доброте и приключениях. А что выбираешь ты?","Что тебя увлекает: язык, мир книги или персонажи?","Какой эпизод или герой показывает это лучше всего?","Согласен ли ты с решением героя? Почему?","С какой мыслью хотелось бы остаться после этой книги?"),
   new Topic("Твой день",@"день|дня|сегодняшн\w*","Какой момент сегодняшнего дня запомнился — приятный, трудный или просто необычный?","Мой день здесь складывается из наших разговоров и лисьих анимаций. А какая часть твоего дня была самой живой?","Что сделало этот момент заметным для тебя?","Хочется повторить что-то из сегодняшнего дня или изменить?","Какую маленькую заботу о себе можно оставить на вечер?","Что хотелось бы пожелать себе на завтра?")
  };
  int nextBatch,step;Topic[] offered;Topic active;string lastDetail="",subject="",aspect="";DateTime touched;readonly HashSet<string> asked=new HashSet<string>();
  public bool Active {get{return active!=null;}}
  static bool Has(string t,string pattern){return Regex.IsMatch(t,@"\b(?:"+pattern+@")\b");}
  // Only a direct request controls the conversation; reports about somebody else do not.
  static string Request(string text){string t=Intent.Normalize(text);t=Regex.Replace(t,@"\bпожалуйста\b","");t=Regex.Replace(t,@"\s+"," ").Trim();return Regex.Replace(t,@"^(?:(?:ну|ладно|хорошо|а|да|все|давай|давайте|лисичка|лисонька|слушай|может|теперь|лучше)\s+)+","");}
  public bool Related(string text){if(active==null)return false;string t=Intent.Normalize(text);if(Has(t,active.Pattern)||(subject.Length>0&&t.Contains(Intent.Normalize(subject))))return true;
   string pattern=active.Name=="Книги"||active.Name=="Фильмы и сериалы"?@"геро\w*|персонаж\w*|мир|мира|атмосфер\w*|дракон\w*|сюжет\w*|эпизод\w*|автор\w*|стиль|язык|диалог\w*|описани\w*|спойлер\w*|читаю|дочитал\w*|прочитал\w*|закончил\w*|фэнтези|фантастик\w*|детектив\w*|романтик\w*":active.Name=="Музыка"?@"звучани\w*|мелоди\w*|ритм\w*|текст\w*|слов\w*|исполнител\w*|гитар\w*|альбом\w*|концерт\w*":active.Name=="Игры"?@"друз\w*|вместе|компани\w*|побед\w*|исследован\w*|строительств\w*|квест\w*|рейд\w*":active.Name=="Путешествия"?@"город\w*|мор[ея]|озер\w*|природ\w*|отпуск\w*|стран\w*":active.Name=="Уют и отдых"?@"плед\w*|тишин\w*|прогул\w*|чай|дома":active.Name=="Мечты и планы"?@"шаг\w*|попробовать|научиться|начать|цель\w*":active.Name=="Воспоминания"?@"вспом\w*|помню|тогда|детств\w*":@"сегодня|утром|вечером|днем";
   return Has(t,pattern);
  }
  static bool Is(string t,string pattern){return Regex.IsMatch(t,@"^(?:"+pattern+@")$");}
  void Expire(){if(touched!=default(DateTime)&&DateTime.Now-touched>TimeSpan.FromMinutes(30)){active=null;offered=null;}}
  public void End(){active=null;offered=null;lastDetail="";subject="";aspect="";asked.Clear();}
  string Ask(string question){return asked.Add(question)?question:"Можно добавить то, что тебе важно, или попросить другую тему.";}
  string NextQuestion(){while(step<active.Questions.Length){string q=active.Questions[step++];if(asked.Add(q))return q;}return "Можем остаться с этой темой: расскажи то, что ещё хочется добавить. Или напиши «другие темы».";}
  static string TitleFrom(string text){string value=Regex.Replace(text.Trim(),@"^(?:(?:я\s+)?(?:читаю|читал|читала|прочитал|прочитала|смотрю|смотрел|смотрела)\s+)?(?:(?:книг[ау]|фильм|роман|сериал)\s+)?","",RegexOptions.IgnoreCase).Trim(' ','«','»','"','.','!');return value;}
  bool NamedWork {get{return active!=null&&(active.Name=="Книги"||active.Name=="Фильмы и сериалы");}}
  string Memory(){return "Мы говорим о теме «"+active.Name+"». "+(subject.Length>0?"Название: «"+subject+"». ":"")+(lastDetail.Length>0?"Ты поделился: «"+lastDetail+"». ":"");}
  public string Suggest(){End();offered=Enumerable.Range(0,3).Select(i=>topics[(nextBatch+i)%topics.Length]).ToArray();nextBatch=(nextBatch+3)%topics.Length;touched=DateTime.Now;return "Давай выберем что-нибудь по душе 🧡\n"+string.Join("\n",offered.Select((t,i)=>(i+1)+". "+t.Name))+"\nНапиши номер, название или «выбери сама». Можно попросить другие темы.";}
  public Reply Control(string text){Expire();string t=Intent.Normalize(text);
   string request=Request(text);
   if(Regex.IsMatch(request,@"^(?:(?:я )?не (?:хочу|надо|нужно|будем) (?:пока )?(?:менять|заканчивать|закрывать|завершать|прекращать)|не (?:меняй|заканчивай|закрывай|завершай|прекращай))\b"))return new Reply(active!=null?"Хорошо, остаёмся с этой темой. Слушаю тебя 🧡":"Хорошо, я слушаю 🧡");
   var destination=Regex.Match(request,@"(?:^|\b(?:и|а|теперь|лучше)\s+)(?:(?:(?:я )?хочу|хотелось бы|можно|можем|можешь|давай|давайте)\s+)?(?:(?:просто|немного|лучше|теперь)\s+)?(?:(?:(?:поговорить|поговорим|поболтать|поболтаем|пообщаться|пообщаемся|говорить)\s+(?:(?:с тобой|со мной)\s+)?)?(?:о|об|про|насчет)|(?:обсудим|обсудить))\s+(?<topic>.+)$");
   if(destination.Success&&!Has(destination.Groups["topic"].Value,@"друг\w*|что нибудь|чем нибудь")&&!Regex.IsMatch(request,@"^(?:о чем|про что)\b")){
    string target=destination.Groups["topic"].Value;Topic selected=topics.FirstOrDefault(x=>target==Intent.Normalize(x.Name)||Is(target,x.Pattern));
    if(selected!=null)return Choose(selected);
    // An explicit unknown destination must also release the old topic.
    End();return new Reply("Хорошо, оставим прежнюю тему. Расскажи, что именно хочешь обсудить: «"+target+"». Я слушаю 🧡");
   }
   bool change=Regex.IsMatch(request,@"^(?:(?:я )?хочу |можно |можем |можешь |давай )?(?:(?:поменя(?:й|ем|ть)|смен(?:и|им|ить)|измен(?:и|им|ить))\s+(?:эту |нашу )?тему|переключ(?:ись|имся|иться)\s+на\s+(?:друг\w*|нов\w*))\b")||Regex.IsMatch(request,@"^(?:(?:я )?хочу |хотелось бы |можно |можем |давай )?(?:(?:лучше |просто )?(?:поговорим|поговорить|поболтать|поболтаем|пообщаться|пообщаемся)\s+)?(?:о|об|про|на)\s+(?:(?:чем|чем то|чем нибудь|что|что то|что нибудь)\s+)?(?:друг\w*|нов\w*)\b")||Is(request,@"(?:другую|другая|другие|новую|новая|еще) тем\w*|предложи что нибудь");
   bool suggest=Regex.IsMatch(request,@"^(?:(?:ты )?(?:можешь|могла бы) )?(?:предложи|предложить|придумай|подскажи|посоветуй|выбери)\b.{0,35}\bтем\w*\b|^(?:о чем|про что)\s+(?:нам\s+)?(?:поговорим|поговорить|поболтать|поболтаем)\b");
   change=change||Regex.IsMatch(request,@"^(?:(?:я )?хочу |можно |можем )?(?:обсудим|обсудить|начнем|начать|выберем|выбрать)\s+(?:что нибудь другое|друг\w* тему|нов\w* тему)\b")||Is(request,@"(?:что нибудь |что то )?другое|другую");
   if(change||suggest)return new Reply(Suggest());
   bool stop=Is(request,@"не хочу|не сейчас|хватит|стоп|закончим|помолчим|замолчи|хватит об этом")||Regex.IsMatch(request,@"^(?:(?:я )?хочу |можно |можем |давай )?(?:законч(?:им|ить)|заверш(?:им|ить|и)|закро(?:ем|й|ть)|прекрат(?:им|ить|и)|остав(?:им|ить)|отлож(?:им|ить|и))\s+(?:(?:эту|эту самую|текущую|нашу|уже|пока)\s+)*(?:тему|разговор|обсуждение|беседу)\b")||Regex.IsMatch(request,@"^(?:хватит|перестань|прекрати)\s+(?:(?:уже|пока)\s+)?(?:о|об|про|говорить|обсуждать|спрашивать)\b")||Regex.IsMatch(request,@"^(?:я )?(?:(?:больше|сейчас|уже) )?не (?:хочу|буду|надо|нужно)\s+(?:(?:больше|уже|сейчас|пока)\s+)?(?:(?:об этом|про это|на эту тему)\s+)?(?:говорить|обсуждать|разговаривать|продолжать)\b")||Is(request,@"не будем (?:об этом|про это)|мне (?:надоела|неинтересна) (?:эта )?тема");
   stop=stop||Regex.IsMatch(request,@"^(?:с (?:этой |текущей )?темой (?:закончили|закончим)|(?:закончим|закончить|закончили) с (?:этой |текущей )?темой|(?:закончим|закончили|закончи) (?:эту )?тему|не хочу (?:больше )?(?:об этом|про это))\b");
   if(stop){End();return new Reply("Хорошо, тему закончили. Можем просто поболтать или побыть в тишине 🧡");}
   request=Regex.Replace(request,@"(?: на любую тему| о чем нибудь| ни о чем)$","");request=Regex.Replace(request,@"^(?:я )?хочу с тобой ","хочу ");
   if(Is(request,@"(?:(?:я )?(?:хочу|хочется)|мне хочется|можно|можем)?\s*(?:просто |немного )?(?:поговорить|поговорим|поболтать|поболтаем|пообщаться|пообщаемся)(?: с тобой| со мной)?|(?:поговори|поболтай|пообщайся) со мной|хочу (?:просто )?общения")){End();return new Reply("Давай просто поболтаем 🧡 Что у тебя сейчас на уме? Можно начать с чего угодно, а если захочешь — предложу тему.");}
   if(active!=null&&Is(t,@"о чем мы говорили|какая у нас тема|напомни тему|что я сказал|что я говорила|какую книгу я назвал|какую книгу я читаю|помнишь название"))return new Reply(Memory()+"Можем продолжить или выбрать другую 🧡");
   if(active!=null&&Is(t,@"начнем заново|начнем сначала|давай сначала")){step=0;subject="";lastDetail="";aspect="";asked.Clear();return new Reply(active.Opening);}
   if(NamedWork&&subject.Length>0&&Intent.Normalize(TitleFrom(text))==Intent.Normalize(subject)){touched=DateTime.Now;return new Reply("Да, «"+subject+"» — название помню. "+Ask("Ты хочешь рассказать о своих впечатлениях или задать вопрос об этом произведении?")+" 🧡");}
   Topic chosen=null;
   if(offered!=null){int index=Is(t,@"(?:давай |про |выбираю |хочу )?(?:1|первую|первое|первая)(?: тему)?")?0:Is(t,@"(?:давай |про |выбираю |хочу )?(?:2|вторую|второе|вторая)(?: тему)?")?1:Is(t,@"(?:давай |про |выбираю |хочу )?(?:3|третью|третье|третья)(?: тему)?")?2:-1;if(index>=0)chosen=offered[index];if(Is(t,@"выбери сама|на твой выбор|любую|давай|да"))chosen=offered[0];}
   bool explicitTopic=Regex.IsMatch(t,@"^(?:давай|поговорим|хочу поговорить|давай поговорим|давай поболтаем)\s+(?:о|об|про)\s+");
   if(chosen==null&&(offered!=null||active!=null||explicitTopic)){string title=Regex.Replace(t,@"^(?:(?:давай(?: поговорим| поболтаем)?|поговорим|хочу поговорить)\s+)?(?:(?:о|об|про)\s+)?","");chosen=topics.FirstOrDefault(x=>title==Intent.Normalize(x.Name)||Is(title,x.Pattern));}
   if(chosen!=null)return Choose(chosen);
   if(offered!=null&&Is(t,@"не знаю|не могу выбрать|затрудняюсь"))return new Reply("Можно начать без выбора: предложу «"+offered[0].Name+"». Напиши «давай», и начнём, или «другие темы» 🧡");
   return null;
  }
  Reply Choose(Topic chosen){touched=DateTime.Now;if(chosen==active)return new Reply("Да, продолжаем тему «"+active.Name+"». "+(subject.Length>0?"Обсуждаем «"+subject+"». ":"")+"Можешь продолжить с того места, на котором остановились 🧡");End();active=chosen;step=0;return new Reply("Поговорим о теме «"+active.Name+"» 🧡 "+active.Opening);}
  public Reply Continue(string text){Expire();if(active==null)return null;string t=Intent.Normalize(text);touched=DateTime.Now;
   if(Is(t,@"а ты|а тебе|а у тебя|а что тебе нравится|что бы ты выбрала|твой выбор"))return new Reply(active.Self+" 🧡");
   if(Is(t,@"не знаю|не помню|сложно сказать|без понятия"))return new Reply("Необязательно сразу находить ответ. "+NextQuestion()+" 🧡");
   bool related=Related(text),brief=Is(t,@"да|нет|ага|давай|дальше|продолжай|продолжим|еще|давай дальше");
   if(NamedWork&&(related||Is(t,@"о чем она|о чем он|ты ее читала|ты его смотрела"))&&Regex.IsMatch(t,@"\b(?:о чем (?:она|он|эта книга)|расскажи (?:о|об|сюжет)|кто автор|ты (?:ее |его )?(?:знаешь|читала|смотрела)|что ты знаешь|кто (?:такой|такая))\b"))return new Reply("У меня нет надёжной справки"+(subject.Length>0?" о «"+subject+"»":" об этом произведении")+", поэтому сюжет и факты я не буду придумывать. Могу обсудить твои впечатления или отрывок, который ты приведёшь 🧡");
   // A title may be a short unknown phrase. A new question, subject or full statement is not automatically an answer.
   if(!related&&!brief&&(ConversationAnalyzer.HasSubject(text)||text.Contains("?")||t.Split(' ').Length>6||(!NamedWork||subject.Length>0)&&!Regex.IsMatch(t,@"^(?:это|этот|эта|они|он|она|там|тогда|потому что|из за)\b"))){End();return null;}
   if(NamedWork&&subject.Length==0&&text.Length<100&&!Regex.IsMatch(t,@"\b(?:да|нет|мне|нравится|люблю|герои|герой|персонажи|мир|сюжет|язык|атмосфера|фэнтези|фантастика|детектив|романтика|дальше|продолжай)\b")){subject=TitleFrom(text);lastDetail="";if(active.Name=="Книги")return new Reply("Поняла, речь о книге «"+subject+"». "+Ask("Ты ещё читаешь её или уже закончил? Буду осторожна со спойлерами 🧡"));return new Reply("Поняла, обсуждаем «"+subject+"». "+NextQuestion()+" 🧡");}
   if(active.Name=="Книги"&&subject.Length>0){
    if(Regex.IsMatch(t,@"\b(?:дочитал\w*|прочитал\w*|закончил\w*|читаю|начал\w*)\b"))return new Reply(Regex.IsMatch(t,@"не дочитал|еще читаю|только начал")?"Тогда обсудим только то, до чего ты дошёл. "+Ask("Что уже успело тебя заинтересовать?"):"Поняла. "+Ask("Какое впечатление оставила книга — увлекла, разочаровала или вызвала смешанные чувства?"));
    if(Regex.IsMatch(t,@"\b(?:персонаж\w*|геро\w*)\b")){aspect="герои";return new Reply("Давай о героях. "+Ask("Кто тебе особенно интересен и чем — характером, поступками или тем, как меняется?"));}
    if(Regex.IsMatch(t,@"\b(?:мир|мира|атмосфер\w*)\b")){aspect="мир";return new Reply("Тебя заинтересовал мир книги. "+Ask("Какая его деталь запомнилась: устройство мира, места или существа?"));}
    if(Regex.IsMatch(t,@"\bдракон\w*\b")){aspect="драконы";return new Reply("Драконы — давай остановимся на них. "+Ask("Что тебе в них интересно: характер, способности или отношения с людьми?"));}
    if(Regex.IsMatch(t,@"\b(?:язык|стиль|написан\w*)\b")){aspect="стиль";return new Reply("Тогда обсудим, как книга написана. "+Ask("Тебе ближе описания, диалоги или темп повествования?"));}
    if(Regex.IsMatch(t,@"\b(?:сюжет|событи\w*|поворот\w*)\b")){aspect="сюжет";return new Reply("Давай о сюжете. "+Ask("Какой поворот или выбор персонажа тебе хочется обсудить?"));}
   }
   bool forward=Is(t,@"да|ага|давай|дальше|продолжай|продолжим|еще|давай дальше");
   if(!forward){lastDetail=Regex.Replace(text,@"\s+"," ").Trim();if(lastDetail.Length>120)lastDetail=lastDetail.Substring(0,117)+"…";}
   string lead=forward?"Продолжим 🧡 ":aspect.Length>0?"Продолжим обсуждать: "+aspect+". ":"Поняла. ";
   if(active.Name=="Музыка"&&Regex.IsMatch(t,@"\b(?:рок|рока|роком)\b"))lead="В роке можно любить и энергию, и тексты, и звучание инструментов. ";
   if(active.Name=="Игры"&&Regex.IsMatch(t,@"\b(?:друз\w*|вместе|компани\w*)\b"))lead="Похоже, общая игра для тебя связана ещё и с общением. ";
   return new Reply(lead+NextQuestion()+" 🧡");
  }
 }
}
